return ['domain'=>'acfml','plural-forms'=>'nplurals=1; plural=0;','language'=>'zh_CN','project-id-version'=>'Advanced Custom Fields Multilingual 5.2.0','pot-creation-date'=>'2026-10-20 11:28+0000','po-revision-date'=>'2026-10-20 11:28+0000','x-generator'=>'PTC (Private Translation Cloud)','messages'=>['Advanced Custom Fields Multilingual'=>'Advanced Custom Fields Multilingual','https://wpml.org/documentation/wpml-core-and-add-on-plugins/acfml/'=>'https://wpml.org/documentation/wpml-core-and-add-on-plugins/acfml/','Adds compatibility between WPML and Advanced Custom Fields | <a href="https://wpml.org/documentation/translating-your-contents/acf/?utm_source=plugin&utm_medium=gui&utm_campaign=acfml">Documentation</a>'=>'增加 WPML 和 Advanced Custom Fields 之间的兼容性 | <a href="https://wpml.org/documentation/translating-your-contents/acf/?utm_source=plugin&utm_medium=gui&utm_campaign=acfml">文档</a>','OnTheGoSystems'=>'OnTheGoSystems','http://www.onthegosystems.com/'=>'http://www.onthegosystems.com/','Displayed when editing an ACF field in a translation, showing its value in the original language; %1$s and %2$s turn the string into bold, and %3$s is the actual original value.%1$sOriginal%2$s: %3$s'=>'%1$s原文%2$s：%3$s','This type of ACF field will always be set to "Copy once".'=>'此类 ACF 字段将始终设置为“仅复制一次”。','ACF field name:'=>'ACF 字段名称：','ACF field type:'=>'ACF 字段类型：','Translation preferences'=>'翻译首选项','What to do with field\'s value when post/page is going to be translated'=>'当文章/页面将被翻译时，如何处理字段值','Translate (your current setting, no longer offered for this field type)'=>'翻译（您当前的设置，不再为此字段类型提供）','Kept because it is your current setting. This value is no longer offered for this field type.'=>'保留此项是因为它是您当前的设置。此值不再为此字段类型提供。','Not recommended for this field type.'=>'不建议用于此字段类型。','Translated pages start without this content.'=>'已翻译页面开始时不包含此内容。','Editable in other languages, and starts empty.'=>'可在其他语言中编辑，且初始为空。','Visitors in every language always see exactly what the original shows.'=>'每种语言的访客看到的始终与原文完全一致。','Shown locked in other languages, so it cannot be edited there.'=>'在其他语言中显示为已锁定，因此无法在其中进行编辑。','Starts the same as the original, then each language goes its own way.'=>'初始与原文相同，然后每种语言独立进行修改。','Editable in every language, and permanently yours to maintain by hand.'=>'可在每种语言中编辑，并由您永久手动维护。','Visitors see this in their own language.'=>'访客以其自己的语言查看此内容。','Filled by the translation and edited in the translation editor.'=>'由翻译填充并在翻译编辑器中编辑。','Edit the field to set the translation preference.'=>'编辑字段以设置翻译首选项。','ACFML is updating translation preferences for strings in Gutenberg Blocks. Keep using your site as usual. This notice will disappear when the process is done.'=>'ACFML 正在更新 Gutenberg 区块中字符串的翻译首选项。请照常使用您的站点。此通知将在过程完成后消失。','ACFML is enabled but not effective. It requires WPML in order to work.'=>'ACFML 已启用但未生效。它需要 WPML 才能工作。','ACFML is enabled but not effective. It requires Advanced Custom Fields or ACF PRO in order to work.'=>'ACFML 已启用但未生效。它需要安装并启用 Advanced Custom Fields 或 ACF PRO 才能正常工作。','Activate Advanced Custom Fields'=>'激活 Advanced Custom Fields','Install Advanced Custom Fields'=>'安装 Advanced Custom Fields','Field groups are set to "Translatable" in WPML settings, which prevents ACF fields from being translated.'=>'字段组在 WPML 设置中被设置为“可翻译”，这会阻止 ACF 字段被翻译。','This is almost never intended.'=>'这几乎从不是预期的行为。','A configuration file (wpml-config.xml) controls this setting on this site, so it cannot be changed from here. Edit that file, or ask whoever maintains it to set the ACF field group post type to Not translatable.'=>'配置文件 (wpml-config.xml) 控制此站点上的此设置，因此无法在此处更改。请编辑该文件，或要求维护者将 ACF 字段组文章类型设置为不可翻译。','Field group copies already created in other languages stay on the site. Changing this setting does not delete them.'=>'已在其他语言中创建的字段组副本将保留在站点上。更改此设置不会删除它们。','Set field groups to Not translatable'=>'将字段组设置为不可翻译','Why this matters'=>'为什么这很重要','If any field is set to "Translatable", WPML will re-translate the %d posts using this field group.'=>'如果任何字段被设置为“可翻译”，WPML 将使用此字段组重新翻译这 %d 篇文章。','Some posts using this field group have translations. Once you change the translation option, WPML needs to update the translation status of the posts. This can take up to 1 minute.'=>'使用此字段组的部分文章已有翻译。一旦您更改翻译选项，WPML 需要更新文章的翻译状态。这可能需要长达 1 分钟。','Some posts using this field group have translations. Once you change the translation option, WPML needs to update the translation status of the posts. This can take up to %d hours.'=>'使用此字段组的部分文章已有翻译。一旦您更改翻译选项，WPML 需要更新文章的翻译状态。这可能需要长达 %d 小时。','Some posts using this field group have translations. Once you change the translation option, WPML needs to update the translation status of the posts. This can take up to %d minutes.'=>'使用此字段组的部分文章已有翻译。一旦您更改翻译选项，WPML 需要更新文章的翻译状态。这可能需要长达 %d 分钟。','Locked by WPML so that ACF fields stay translatable. Click here to unlock and change it anyway.'=>'由 WPML 锁定以确保 ACF 字段保持可翻译状态。点击此处仍可解锁并更改。','Set translation preferences for the attached taxonomy'=>'为关联的分类法设置翻译首选项','Set translation preferences for the attached post type'=>'为关联的文章类型设置翻译首选项','If you want to translate your fields, go to the WPML Settings page and make the taxonomy attached to this field group translatable. '=>'如果您想翻译字段，请前往 WPML 设置页面，并将关联到此字段组的分类法设为可翻译。 ','If you want to translate your fields, go to the WPML Settings page and %1$smake the post type attached to this field group translatable%2$s.'=>'如果您想翻译字段，请前往 WPML 设置页面并%1$s将关联到此字段组的文章类型设为可翻译%2$s。','Expert'=>'专家','Same content in every language, translated'=>'在每种语言中使用相同的内容，并进行翻译','Each language has its own content'=>'每种语言拥有独立的内容','Translate is not offered on container fields, because it replaces the value your theme reads. The fields inside carry their own preferences.'=>'容器字段不提供“翻译”选项，因为它会替换您的主题读取的值。其中的字段带有各自的首选项。','Translate lets each language point at its own address, which an external link often needs. A link to a page on this site already points at that page in the reader\'s language, so leave it as it is.'=>'“翻译”允许每种语言指向自己的地址，这通常是外部链接所需要的。指向本站页面的链接已经指向了读者语言的页面，因此请保持原样。','Translate sends the link text and the URL. The target keeps the value you set, and a URL you leave as it is points at the page in the reader\'s language.'=>'“翻译”会发送链接文本和 URL。目标保留您设置的值，而您保持原样的 URL 会指向读者语言的页面。','Translating an address produces one that does not exist. An e-mail address is the same in every language.'=>'翻译地址会产生一个不存在的地址。电子邮件地址在每种语言中都是相同的。','A color code is not language content. Translating it changes the color your visitors see.'=>'颜色代码不是语言内容。翻译它会改变访客看到的颜色。','The stored value is a fixed date format that your theme reads. Translating it breaks the format.'=>'存储的值是您的主题读取的固定日期格式。翻译它会破坏格式。','The stored value is the choice key, not the label your visitors see. Translating it stops the key from matching your choices. Translate the labels in <b>String Translation</b> instead.'=>'存储的值是选项键，而不是访客看到的标签。翻译它会导致键与您的选项不匹配。请改为在<b>字符串翻译</b>中翻译标签。','This value is read by your theme or plugin code. A translated value can stop matching what the code expects.'=>'此值由您的主题或插件代码读取。翻译后的值可能无法匹配代码的预期。','The file decides this again on every import, so changes made elsewhere do not stick.'=>'该文件在每次导入时都会再次决定此项，因此在其他地方所做的更改不会生效。','Edit %s, or remove the entry there, to manage this field on this screen.'=>'编辑 %s，或删除其中的条目，以便在此屏幕上管理此字段。','Edit the configuration file, or remove the entry there, to manage this field on this screen.'=>'编辑配置文件，或删除其中的条目，以便在此屏幕上管理此字段。','That is not the value selected above. Saving this field group applies the value above.'=>'那不是上面选择的值。保存此字段组将应用上面的值。','This field group is also in %s. That file re-applies these settings the next time the group is synced.'=>'此字段组也存在于 %s 中。该文件将在下次同步组时重新应用这些设置。','Locked. Managed by your theme, in its wpml-config.xml file.'=>'已锁定。由您的主题在其 wpml-config.xml 文件中管理。','Locked. Managed by a plugin, in its wpml-config.xml file.'=>'已锁定。由插件在其 wpml-config.xml 文件中管理。','Locked. Managed by a configuration file WPML downloaded for one of your plugins or themes.'=>'已锁定。由 WPML 为您的某个插件或主题下载的配置文件管理。','Locked. Managed by the custom XML configuration saved in WPML settings.'=>'已锁定。由 WPML 设置中保存的自定义 XML 配置管理。','Locked. Managed by a configuration file on this site.'=>'已锁定。由该站点上的配置文件管理。','Set in the field group "%s", which uses the same field name.'=>'在字段组“%s”中设置，该组使用相同的字段名称。','Set in the field group\'s local JSON file.'=>'在字段组的本地 JSON 文件中设置。','Set in the field group\'s local JSON file, %s.'=>'在字段组的本地 JSON 文件 %s 中设置。','Registered with PHP by your theme or a plugin.'=>'由您的主题或插件通过 PHP 注册。','Set on the WPML Settings screen (Custom Fields Translation).'=>'在 WPML 设置屏幕（自定义字段翻译）中设置。','Set here, on this screen.'=>'在此屏幕上设置。','Right now this field is translated, so visitors see it in their own language.'=>'目前此字段已翻译，因此访客以其自己的语言查看它。','Right now this field stays identical in every language.'=>'目前此字段在每种语言中保持一致。','Right now this field starts as a copy in every language, then each language keeps its own.'=>'目前此字段在每种语言中初始为副本，然后每种语言保留其各自的内容。','Right now this field stays out of translations.'=>'目前此字段不包含在翻译中。','Don\'t translate'=>'不翻译','Copy'=>'复制','Copy once'=>'仅复制一次','Translate'=>'翻译','Field groups'=>'字段组','Fields'=>'字段','Posts'=>'文章','Review them one by one'=>'逐一审核','Apply the recommended setup to %d group'=>'将推荐设置应用于全部 %d 个','%d ACF field group is not configured for translation.'=>'%d 个 ACF 字段组尚未配置翻译。','%d post'=>'%d 篇文章','%1$s field, used on %2$s, would be skipped and stay in %3$s.'=>'在 %2$s 上使用的 %1$s 个字段将被跳过并保留在%3$s中。','%1$s field, used on %2$s, would be skipped and stay untranslated.'=>'在 %2$s 上使用的 %1$s 个字段将被跳过且保持未翻译状态。','You are not allowed to change the translation setup of ACF field groups.'=>'您无权更改 ACF 字段组的翻译设置。','You are not allowed to change the WPML translation settings on this site.'=>'您无权更改此站点上的 WPML 翻译设置。','To change the translation options for custom fields, edit the field group "%s".'=>'要更改自定义字段的翻译选项，请编辑字段组“%s”。','These fields come from ACF’s Local JSON files. To change their translation options, go to ACF → Field Groups, sync them, and then edit their settings.'=>'这些字段来自 ACF 的本地 JSON 文件。要更改其翻译选项，请前往 ACF → 字段组，同步它们，然后编辑其设置。','This field and its translation setting are registered via PHP by your theme or plugin. Changes made here will override the original configuration.'=>'此字段及其翻译设置由您的主题或插件通过 PHP 注册。在此处所做的更改将覆盖原始配置。','ACF translation setup'=>'ACF 翻译设置','Translation setup'=>'翻译设置','You are not allowed to review the translation setup of ACF field groups.'=>'您无权审核 ACF 字段组的翻译设置。','Field group'=>'字段组','Setup'=>'设置','Actions'=>'操作','This site has no ACF field groups yet.'=>'此站点尚无 ACF 字段组。','Alert:'=>'警报：','How to do that'=>'如何操作','View fields'=>'查看字段','Open Dashboard'=>'打开仪表板','Apply the recommended setup'=>'应用推荐设置','Every field group stored in this site’s database already has a translation setup.'=>'存储在此站点数据库中的每个字段组都已有翻译设置。','Back to the field groups'=>'返回字段组列表','Every field in those groups then gets the translation preference WPML recommends for its field type. A preference that was set by hand in one of them is replaced.'=>'这些组中的每个字段随后都会获得 WPML 为其字段类型推荐的翻译首选项。其中手动设置的首选项将被替换。','Field groups that come from your theme, a plugin’s code, or an acf-json file are not changed. They cannot be saved from here.'=>'来自您的主题、插件代码或 acf-json 文件的字段组不会被更改。它们无法在此处保存。','Cancel'=>'取消','%d field group.'=>'%d 个字段组。','All of them have a translation setup.'=>'它们都已有翻译设置。','%d is not configured.'=>'%d 个未配置。','Apply recommended setup to the %d unconfigured group'=>'将推荐设置应用于全部 %d 个未配置的组','This sets %1$d field group to “%2$s”.'=>'这会将 %1$d 个字段组设置为“%2$s”。','%d field group is defined in code, so it cannot be configured from here.'=>'%d 个字段组在代码中定义，因此无法在此处进行配置。','Not configured'=>'未配置','Not configured (defined in code)'=>'未配置（在代码中定义）','Set for each field (defined in code)'=>'为每个字段设置（在代码中定义）','Set for each field in WPML Settings (defined in code)'=>'针对 WPML 设置中的每个字段进行设置（在代码中定义）','%d field set manually'=>'%d 个字段已手动设置','Nothing decides how these fields are translated. Set %s on the fields in the code that registers this group.'=>'没有任何项决定这些字段如何翻译。请在注册此组的代码中的字段上设置 %s。','from an acf-json file'=>'来自 acf-json 文件','from an acf-json file that is newer than this site’s copy'=>'来自比此站点副本更新的 acf-json 文件','from your theme or a plugin’s code'=>'来自您的主题或插件代码','%d field group now uses the recommended setup.'=>'%d 个字段组现在使用推荐设置。','%d field group has a newer acf-json file waiting to be synced, so that file decides its setup.'=>'%d 个字段组有较新的 acf-json 文件等待同步，因此将由这些文件决定其设置。','Translation Option'=>'翻译选项','Multilingual Setup'=>'多语言设置','Loading...'=>'正在加载...','Activate <b>String Translation</b>'=>'激活 <b>String Translation</b>','To translate field group names and labels, please %1$sinstall and activate WPML’s String Translation add-on%2$s.'=>'要翻译字段组名称和标签，请%1$s安装并激活 WPML 的 String Translation 附加组件%2$s。','Activate now'=>'立即激活','Go back'=>'返回','Set Up <b>Field Group Translation</b>'=>'设置<b>字段组翻译</b>','To translate field labels from the <b>Translation Management</b> dashboard, finish the <b>Multilingual Setup</b> and save your field group settings.'=>'要从<b>翻译管理</b>仪表板翻译字段标签，请完成<b>多语言设置</b>并保存您的字段组设置。','OK'=>'确定','Translate Field Labels'=>'翻译字段标签','To translate field labels, use the <b>Translation Management</b> dashboard.'=>'要翻译字段标签，请使用<b>翻译管理</b>仪表板。','Translate in <b>Translation Management</b>'=>'在<b>翻译管理</b>中翻译','Don’t want to translate field labels? %1$sLearn how to disable field label translation%2$s'=>'不想翻译字段标签？%1$s了解如何禁用字段标签翻译%2$s','Field Labels Partly Translated'=>'字段标签已部分翻译','Some field labels in this group are still untranslated. To finish translating them, go to the <b>Translation Management</b> dashboard.'=>'此组中的某些字段标签仍未翻译。要完成翻译，请前往<b>翻译管理</b>仪表板。','Fields Labels Already Translated'=>'字段标签已全部翻译','You already translated all field labels in this group. To update any translations, go to the <b>Translation Management</b> dashboard.'=>'您已翻译此组中的所有字段标签。要更新任何翻译，请前往<b>翻译管理</b>仪表板。','Go to <b>Translation Management</b>'=>'前往<b>翻译管理</b>','Select a translation option for this field group'=>'为此字段组选择一个翻译选项','Visitors everywhere see the same pages, in their own language. Text is translated; layout and settings stay identical.'=>'各地访客以其自己的语言查看相同的页面。文本会被翻译；布局和设置保持一致。','You translate in the WPML <b>Translation Editor</b>. This works with automatic translation and <b>Translate Everything</b>.'=>'您在 WPML <b>翻译编辑器</b>中进行翻译。这适用于自动翻译和<b>翻译所有内容</b>。','Every language’s pages are written and maintained on their own. Fields start as a copy of the original, then go their own way.'=>'每种语言的页面都是独立编写和维护的。字段初始为原文的副本，然后独立修改。','You edit each language in the WordPress editor. WPML does not sync them afterwards, and automatic translation does not apply.'=>'您在 WordPress 编辑器中编辑每种语言。WPML 随后不会同步它们，且自动翻译不适用。','If you are migrating a site, your existing field groups will use the Expert setup. This allows you to manually choose the translation option for each field in the group.'=>'如果您正在迁移站点，现有的字段组将使用“专家”设置。这允许您手动为组中的每个字段选择翻译选项。','This option is %1$snot recommended%2$s for new field groups.'=>'对于新字段组，%1$s不推荐%2$s此选项。','Expert setup documentation'=>'专家设置文档','Choose'=>'选择','recommended for this site'=>'为此站点推荐','Change option'=>'更改选项','A Much Simpler Way to Translate Your ACF Sites'=>'翻译 ACF 站点的更简单方法','This new release of ACFML allows you to configure multilingual sites in one-click, instead of many complex settings. Choose how to setup the translation for the fields.'=>'ACFML 的这个新版本允许您一键配置多语言站点，而无需进行许多复杂的设置。请选择如何设置字段的翻译。','Go to WPML Settings'=>'前往 WPML 设置','Need help choosing?'=>'需要帮助选择吗？','Documentation'=>'文档','How to translate field labels »'=>'如何翻译字段标签 »','This setup translates field values.'=>'此设置翻译字段值。','Translate field labels and dropdown choice labels separately. Find them under ACF Field Group in the <b>Translation Dashboard</b>.'=>'单独翻译字段标签和下拉选择标签。在<b>翻译仪表板</b>中的 ACF Field Group 下可以找到它们。','Review these translation setting changes'=>'审核这些翻译设置更改','Saving this field group makes these changes:'=>'保存此字段组将进行以下更改：','%1$s: from “%2$s” to “%3$s”'=>'%1$s：从“%2$s”改为“%3$s”','Switching to the field-by-field setup keeps every field\'s current setting. From here you set each field yourself.'=>'切换到逐个字段设置将保留每个字段的当前设置。您可以从此处自行设置每个字段。','New translations use the new settings automatically.'=>'新翻译将自动使用新设置。','Not set'=>'未设置','No posts with translations use this field group yet, so nothing has to be sent again.'=>'尚无使用此字段组的已翻译文章，因此无需再次发送任何内容。','No terms with translations use this field group yet, so nothing has to be sent again.'=>'尚无使用此字段组的已翻译术语，因此无需再次发送任何内容。','No posts or terms with translations use this field group yet, so nothing has to be sent again.'=>'尚无使用此字段组的已翻译文章或术语，因此无需再次发送任何内容。','Only apply to new translations'=>'仅应用于新翻译','Checking how much content this affects...'=>'正在检查受影响的内容数量...','Save changes'=>'保存更改','No, go back'=>'不，返回','Updating them sends them for translation again, which may use translation words.'=>'更新它们会再次发送翻译，这可能会消耗翻译字数。','Updating them marks their translations as needing an update. WPML does not send them for translation. You can send them from the Translation Dashboard.'=>'更新它们会将对应的翻译标记为需要更新。WPML 不会自动将其发送翻译。您可以从翻译仪表板发送它们。','Switching the setup applies the recommended value to the %d field in this group.'=>'切换设置会将推荐值应用于该组中的全部 %d 个字段。','%d post already has translations that used the old settings.'=>'%d 篇文章已包含使用旧设置生成的翻译。','%d term already has translations that used the old settings.'=>'%d 个术语已包含使用旧设置生成的翻译。','%d post uses this field group.'=>'%d 篇文章使用了此字段组。','%d post is translated by hand, so WPML does not send it for translation.'=>'%d 篇文章为手动翻译，因此 WPML 不会将其发送翻译。','Also update the %d existing post'=>'同时更新现有的 %d 篇文章','Also update the %d existing term'=>'同时更新现有的 %d 个术语','Also update the %1$d existing posts and %2$d terms'=>'同时更新 %1$d 个现有文章和 %2$d 个术语','Also update the %1$d existing post and %2$d terms'=>'同时更新 %1$d 个现有文章和 %2$d 个术语','Also update the %1$d existing posts and %2$d term'=>'同时更新 %1$d 个现有文章和 %2$d 个术语','Also update the %1$d existing post and %2$d term'=>'同时更新 %1$d 个现有文章和 %2$d 个术语','This field group is shown on an Options page.'=>'此字段组显示在选项页面上。','That is usually site-wide content like your header, footer, or global blocks.'=>'那通常是全站内容，如页眉、页脚或全局区块。','To translate that content, use the %1$sWPML Translation Dashboard%2$s.'=>'要翻译该内容，请使用 %1$sWPML 翻译仪表板%2$s。','The options below still decide how each field behaves: translated, copied to every language, or kept separately per language.'=>'以下选项仍决定每个字段的行为：翻译、复制到每种语言或按语言分别保留。','This field group also appears on an Options page.'=>'此字段组也出现在选项页面上。','That content is translated in the %1$sWPML Translation Dashboard%2$s, and the option you choose here decides how each of its fields behaves.'=>'该内容在 %1$sWPML 翻译仪表板%2$s 中进行翻译，您在此处选择的选项决定了其每个字段的行为。','Post Type Translation'=>'文章类型翻译','Labels Translation'=>'标签翻译','Taxonomy Translation'=>'分类翻译','Finish the ACF <b>Multilingual Setup</b>'=>'完成 ACF <b>多语言设置</b>','Before you can start translating, you need to edit each ACF Field Group to set a translation option for the fields inside it.'=>'在开始翻译之前，您需要编辑每个 ACF 字段组，以为其中的字段设置翻译选项。','Read more about %1$show to translate your ACF custom fields%2$s'=>'阅读更多关于%1$s如何翻译您的 ACF 自定义字段%2$s的信息','%1$sSet translation options%2$s'=>'%1$s设置翻译选项%2$s','Let\'s Start Translating!'=>'让我们开始翻译吧！','Edit each Field Group to select a translation option for the fields inside it. If you don\'t set a translation option, you will not be able to translate your fields.'=>'编辑每个字段组，为其中的字段选择翻译选项。如果您不设置翻译选项，将无法翻译您的字段。','A field in "%s" has the same name as a field in another field group. WPML stores translation preferences by field name, so two fields that share a name cannot be set differently.'=>'“%s”中的一个字段与另一个字段组中的字段同名。WPML 按字段名称存储翻译首选项，因此共享名称的两个字段无法进行不同的设置。','Some fields in "%s" have the same name as fields in other field groups. WPML stores translation preferences by field name, so fields that share a name cannot be set differently.'=>'“%s”中的某些字段与其他字段组中的字段同名。WPML 按字段名称存储翻译首选项，因此共享名称的字段无法进行不同的设置。','What you set here may not be what your visitors get'=>'您在此处的设置可能与访客看到的内容不符','The field %1$s also exists in "%2$s". Rename this field to give it a translation setting of its own.'=>'字段 %1$s 也存在于“%2$s”中。请重命名此字段，以便为其提供独立的翻译设置。','See both fields'=>'查看这两个字段','Go to Media Translation settings'=>'前往媒体翻译设置','This content has ACF image, gallery, or file fields, but the alt text, caption, and title of their media will not be sent for translation. To include them, turn on "Translate Media Library texts when translating content" in WPML Media Translation settings.'=>'此内容包含 ACF 图像、画廊或文件字段，但其媒体的替代文本、说明和标题将不会被发送进行翻译。要包含它们，请在 WPML Media Translation 设置中开启“翻译内容时翻译媒体库文本”。','Media texts are not being translated'=>'媒体文本未被翻译','%1$sGo to Media Translation settings%2$s'=>'%1$s前往媒体翻译设置%2$s','Translate this Options page from the <b>Translation Dashboard</b>'=>'从<b>翻译仪表板</b>翻译此选项页面','You no longer need to switch the admin language to translate options manually. Translate all your options from the %1$sTranslation Dashboard%2$s.'=>'您不再需要切换管理语言来手动翻译选项。请从 %1$s翻译仪表板%2$s 翻译您的所有选项。','Go to the Translation Dashboard'=>'前往翻译仪表板','To change a finished translation, go to %1$sTranslation Jobs%2$s and click on the Edit Translation icon.'=>'要更改已完成的翻译，请前往 %1$s翻译作业%2$s 并点击“编辑翻译”图标。','Go to Translation Jobs'=>'前往翻译作业','WPML blocked this save to prevent data loss. The form sent about %1$s fields, but the PHP max_input_vars limit on this server (%2$s) let fewer through. Saving now would permanently delete the fields that did not arrive, including repeater rows. Nothing was saved. Ask your host to raise max_input_vars above %1$s and save again.'=>'WPML 阻止了此次保存以防止数据丢失。表单发送了约 %1$s 个字段，但此服务器上的 PHP max_input_vars 限制 (%2$s) 允许通过的数量较少。现在保存将永久删除未到达的字段，包括重复器行。未保存任何内容。请联系您的主机商将 max_input_vars 提高到 %1$s 以上，然后再次保存。','Save blocked to prevent data loss'=>'已阻止保存以防止数据丢失','You need to %1$stranslate this post manually%2$s because the field groups attached to it use different translation options:'=>'您需要 %1$s手动翻译此文章%2$s，因为与其关联的字段组使用了不同的翻译选项：','and %d more.'=>'以及另外 %d 个。','Show all field groups'=>'显示所有字段组','and %d more'=>'以及另外 %d 个','You need to translate this post manually because the field groups attached to it use different translation options: %s.'=>'您需要手动翻译此文章，因为与其关联的字段组使用了不同的翻译选项：%s。','Edit %s'=>'编辑 %s','Go to documentation'=>'查看文档','This field value is copied from the default language and will be kept in sync across languages.'=>'此字段值是从默认语言复制的，并将在各语言之间保持同步。','Synchronise translations'=>'同步翻译','Keep repeater and flexible sub-fields in the same order as the default language.'=>'保持重复器和灵活内容子字段的顺序与默认语言一致。','ACFML Synchronise translations'=>'ACFML 同步翻译','Translate ACF Local JSON and PHP-Registered Fields'=>'翻译 ACF 本地 JSON 和通过 PHP 注册的字段','ACF allows you to %1$sregister fields via PHP%2$s or %3$ssave field settings as JSON files%4$s. You can also save post types, taxonomies, or options pages settings to JSON files.'=>'ACF 允许您%1$s通过 PHP 注册字段%2$s或%3$s将字段设置保存为 JSON 文件%4$s。您还可以将文章类型、分类法或选项页面设置保存到 JSON 文件中。','Configure how ACF Multilingual handles translations for these items.'=>'配置 ACF Multilingual 如何处理这些项目的翻译。','Sync <b>Translation Preferences</b> for Local Fields'=>'同步本地字段的<b>翻译首选项</b>','Don’t sync translation preferences'=>'不同步翻译首选项','Sync once now'=>'现在同步一次','Sync on every request (may affect performance)'=>'每次请求时同步（可能会影响性能）','Register Labels for Translation'=>'注册标签以进行翻译','Scans post types, taxonomies, options pages, and field groups stored in the "acf-json" directory, then registers their labels with WPML so you can translate them.'=>'扫描存储在 “acf-json” 目录中的文章类型、分类法、选项页面和字段组，然后向 WPML 注册它们的标签，以便您可以翻译它们。','Don’t register labels'=>'不注册标签','Register labels now'=>'现在注册标签','Apply'=>'应用','The synchronization of translation preferences is disabled.'=>'翻译首选项的同步已禁用。','Translation preferences synchronized.'=>'翻译首选项已同步。','The synchronization of translation preferences is enabled.'=>'翻译首选项的同步已启用。','%s group'=>'%s 个组','%s post type'=>'%s 个文章类型','%s taxonomy'=>'%s 个分类法','%s options page'=>'%s 个选项页面','No local field groups, post types, taxonomies, or Options pages were found.'=>'未找到本地字段组、文章类型、分类法或选项页面。','Used between elements of a two elements list and '=>' 和 ','Used before the last element of a three or more elements list, and '=>'，以及 ','Successfully registered labels for %s.'=>'已成功为 %s 注册标签。','%1$sChange translation settings%2$s'=>'%1$s更改翻译设置%2$s','%1$sTranslate labels%2$s'=>'%1$s翻译标签%2$s','Not translatable'=>'不可翻译','Translatable'=>'可翻译','only show translated items'=>'仅显示已翻译的项目','use translation if available or fallback to default language'=>'如果可用则使用翻译，否则回退到默认语言','This content must be translated manually due to the translation option you selected for the "%1$s" field group.'=>'由于您为“%1$s”字段组选择的翻译选项，此内容必须手动翻译。']];